-- Source: FED_PBGC_TRUSTEED_PENSION_PLANS (21596 rows)
-- Generated by scripts/gen_mart_models.py
-- Fixed 2026-09-20: PLAN_EFFECTIVE_DATE was a bare try_to_date() (pure-digit
-- values misread as epoch seconds) and PARTICIPANT_COUNT a bare
-- try_to_number() (silently rounds decimals -- try_to_number('1.5') -> 2). No
-- staging model matches this source: models/staging/fed_pbgc_trusteed_plans
-- reads a DIFFERENT landing table (FED_PBGC_TRUSTEED_PLANS, singular-plan
-- schema with sponsor/plan_number/case_number columns this table doesn't
-- have), so wrapped the two bare casts in place instead of swapping to ref().

with source as (
    select * from {{ source('ripple_raw', 'FED_PBGC_TRUSTEED_PENSION_PLANS') }}
)

select
    PLAN_NAME as plan_name,
    ADMIN_CITY as admin_city,
    ADMIN_STATE as admin_state,
    PLAN_SPONSOR_NAME as plan_sponsor_name,
    CONTACT_PHONE_NUMBER as contact_phone_number,
    {{ stg_date('PLAN_EFFECTIVE_DATE') }} as plan_effective_date,
    PLAN_ID as plan_id,
    EIN as ein,
    PN as pn,
    {{ stg_int('PARTICIPANT_COUNT') }} as participant_count
from source
